#include "resident/domains/interaction/interaction_source_projection.hpp"
// 原约期/回复visitor完全不动；本profile明确承诺语义及两独立持久来源。
#include "visit_appointment_boundary.hpp"
#include "resident/domains/interaction/appointments/personal_appointment_boundary.hpp"
#include <set>
namespace hanmo::resident {namespace {
bool invitation_kind(const StableId& kind){return kind==visit_appointment_offered_kind||kind==visit_appointment_collected_kind||kind==visit_appointment_accepted_kind;}
bool meeting_kind(const StableId& kind){return kind==visit_appointment_meeting_started_kind||kind==visit_appointment_meeting_cancelled_kind||kind==visit_appointment_meeting_finished_kind;}
}
bool is_visit_appointment_command(const StableId& kind){return kind=="offer_visit_appointment"||kind=="collect_visit_appointment"||kind=="accept_visit_appointment";}
bool is_visit_appointment_meeting_command(const StableId& kind){return kind==visit_appointment_meeting_action_kind||kind=="cancel_visit_appointment";}
StableId visit_appointment_meeting_command_kind(const VisitAppointmentMeetingCommand& command){return std::holds_alternative<MeetVisitAppointment>(command)?visit_appointment_meeting_action_kind:"cancel_visit_appointment";}
Outcome<VisitAppointmentMeetingCommand> decode_visit_appointment_meeting_command(const StableId& kind,const BoundaryValue& value){try{using namespace boundary;if(!is_visit_appointment_meeting_command(kind))unsupported("UnsupportedVisitAppointmentCommand",kind);std::set<StableId> names;for(const auto& row:object(value,kind))if(!names.insert(row.first).second)fail("DuplicateVisitAppointmentCommandField",row.first);fields(value,{"invitation_fact_id","acceptance_fact_id"},{},kind);const auto id=get_string(value,"invitation_fact_id",kind),accepted=get_string(value,"acceptance_fact_id",kind);if(id.empty()||id.size()>256||accepted.empty()||accepted.size()>256)fail("InvalidVisitAppointmentCommand",kind);if(kind==visit_appointment_meeting_action_kind)return {true,MeetVisitAppointment{id,accepted},{}};return {true,CancelVisitAppointment{id,accepted},{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
BoundaryValue encode_visit_appointment_quote(const VisitAppointmentQuote& q){using V=BoundaryValue;V::Dict out{{"duration",V{Integer{0}}},{"invitation_fact_id",V{q.invitation_fact_id}}};if(!std::holds_alternative<CollectVisitAppointment>(q.command)){out.emplace_back("policy_id",V{q.policy_id});out.emplace_back("collection_fact_id",V{q.collection_fact_id});out.emplace_back("place_id",V{q.terms.place_id});out.emplace_back("accept_before_tick",V{q.terms.accept_before_tick});out.emplace_back("earliest_tick",V{q.terms.earliest_tick});out.emplace_back("latest_tick",V{q.terms.latest_tick});}return V{std::move(out)};}
BoundaryValue encode_visit_appointment_meeting_quote(const VisitAppointmentMeetingQuote& q,bool action){using V=BoundaryValue;return boundary::obj({{"duration",V{action?Integer{1}:Integer{0}}},{"invitation_fact_id",V{q.invitation_fact_id}},{"acceptance_fact_id",V{q.acceptance_fact_id}},{"place_id",V{q.terms.place_id}},{"earliest_tick",V{q.terms.earliest_tick}},{"latest_tick",V{q.terms.latest_tick}}});}
Outcome<Integer> decode_visit_appointment_profile_version(const BoundaryValue& scenario,const std::vector<StableId>& capabilities){try{
 using namespace boundary;std::set<StableId> names;for(const auto& row:object(scenario,"scenario"))if(!names.insert(row.first).second)fail("DuplicateVisitAppointmentField",row.first);
 const auto* p=scenario.find("visit_appointment_profile"),*catalog=scenario.find("visit_appointment_invitations"),*intents=scenario.find("visit_appointment_intents");
 if(!p){if(catalog||intents)unsupported("VisitAppointmentProfileRequired","visit_appointment_invitations");return {true,0,{}};}
 const auto& chosen=string(*p,"visit_appointment_profile");const Integer version=chosen=="witnessed_visit_appointments_v1"?1:chosen=="witnessed_visit_appointments_time2_v2"?2:0;
 if(!version)unsupported("UnsupportedVisitAppointmentProfile","visit_appointment_profile");if(!catalog)unsupported("VisitAppointmentCatalogRequired","visit_appointment_invitations");
 if(get_int(*catalog,"version","visit_appointment_invitations")!=version)unsupported("VisitAppointmentCatalogVersionMismatch","visit_appointment_invitations");
 auto message=decode_visit_message_profile_version(scenario,capabilities);if(!message.ok)return {false,{},message.error};auto personal=decode_personal_appointment_profile_version(scenario,capabilities);if(!personal.ok)return {false,{},personal.error};
 if(personal.value!=version||(version==1?message.value!=1:(message.value!=2&&message.value!=3)))unsupported("VisitAppointmentOriginalProfileRequired","scenario");
 const auto* capability=version==1?"visit_appointments_v1":"visit_appointments_v2";if(std::find(capabilities.begin(),capabilities.end(),capability)==capabilities.end())unsupported("VisitAppointmentCapabilityRequired",capability);
 if(intents&&std::find(capabilities.begin(),capabilities.end(),"visit_appointment_intents_v1")==capabilities.end())unsupported("VisitAppointmentCapabilityRequired","visit_appointment_intents_v1");return {true,version,{}};
}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Outcome<bool> decode_visit_appointment_profile(const BoundaryValue& scenario,const std::vector<StableId>& capabilities){auto v=decode_visit_appointment_profile_version(scenario,capabilities);return v.ok?Outcome<bool>{true,v.value!=0,{}}:Outcome<bool>{false,{},v.error};}

Status validate_visit_appointment_layout(const CommonStore& common,const std::vector<std::pair<StableId,StableId>>& modules,const VisitAppointmentCatalog* catalog,const VisitAppointmentState* state,const VisitAppointmentMeetingState* meetings,const VisitAppointmentIntentCatalog* intents){
 std::map<StableId,Integer> counts;std::map<StableId,StableId> versions;
 for(const auto&m:modules)if(m.first==visit_appointment_module||m.first==visit_appointment_meeting_module||m.first==visit_appointment_intent_module||m.first=="visit_messages"||m.first=="personal_appointments"||m.first=="visit_reception_intents"||m.first==visit_reception_claim_module){++counts[m.first];versions[m.first]=m.second;}
 const bool enabled=catalog!=nullptr;const Integer selected=enabled?catalog->version:1;
 if(selected==1)for(const auto&v:versions)if(v.second!="1")return common_failure("UnsupportedVisitAppointmentDependencyVersion",v.first);
 if(selected==2)for(const auto&v:versions)if(v.first!=visit_appointment_module&&v.first!=visit_appointment_meeting_module&&v.first!="personal_appointments"&&v.first!="visit_messages"&&v.second!="1")return common_failure("UnsupportedVisitAppointmentDependencyVersion",v.first);
 if((selected!=1&&selected!=2)||counts[visit_appointment_module]!=(enabled?1:0)||counts[visit_appointment_meeting_module]!=(enabled?1:0)||bool(state)!=enabled||bool(meetings)!=enabled||(enabled&&(state->version!=selected||meetings->version!=selected||versions[visit_appointment_module]!=std::to_string(selected)||versions[visit_appointment_meeting_module]!=std::to_string(selected)||counts["visit_messages"]!=1||counts["personal_appointments"]!=1||versions["personal_appointments"]!=std::to_string(selected)||(selected==1?versions["visit_messages"]!="1":(versions["visit_messages"]!="2"&&versions["visit_messages"]!="3"))))||counts[visit_appointment_intent_module]!=(intents?1:0)||(intents&&(!enabled||intents->version!=1||versions[visit_appointment_intent_module]!="1"||counts["visit_reception_intents"]!=1||versions["visit_reception_intents"]!="1"||counts[visit_reception_claim_module]!=1||versions[visit_reception_claim_module]!="1")))return common_failure("VisitAppointmentProfileMismatch");
 if(enabled)return common_success();
 for(const auto&h:common.state().facts.rows())if(invitation_kind(h.second.kind)||meeting_kind(h.second.kind)||h.second.domain==visit_appointment_module||h.second.domain==visit_appointment_meeting_module)return common_failure("VisitAppointmentProfileRequired",h.first);
 for(const auto&a:common.state().actions.rows())if(a.second.kind==visit_appointment_meeting_action_kind)return common_failure("VisitAppointmentProfileRequired",a.first);
 auto valid=validate_visit_appointment_cached_results(common,nullptr);if(!valid.ok)return valid;return validate_visit_appointment_meeting_cached_results(common,nullptr);
}

Outcome<bool> emit_visit_appointment_fact_payload_fields(ProjectionWriter& w,const VisitAppointmentState* state,const VisitAppointmentMeetingState* meetings,const FactRecord& h){const bool a=invitation_kind(h.kind),b=meeting_kind(h.kind);if(!a&&!b&&h.domain!=visit_appointment_module&&h.domain!=visit_appointment_meeting_module)return {true,false,{}};if((!a&&!b)||(a&&(!state||h.domain!=visit_appointment_module))||(b&&(!meetings||h.domain!=visit_appointment_meeting_module)))return {false,{},common_failure("VisitAppointmentFactMismatch",h.id).error};auto status=a?emit_visit_appointment_fact_fields(w,*state,h.id,&h):emit_visit_appointment_meeting_fact_fields(w,*meetings,h.id,&h);return {status.ok,status.ok,status.error};}
Outcome<bool> emit_visit_appointment_action_payload_fields(ProjectionWriter& w,const VisitAppointmentMeetingState* meetings,const ActionCoreView& action){if(action.kind!=visit_appointment_meeting_action_kind)return {true,false,{}};const VisitAppointmentMeetingStarted* start=nullptr;if(meetings)for(const auto& row:meetings->started.rows())if(row.second.action_id==action.id){if(start)return {false,{},common_failure("DuplicateVisitAppointmentAction",action.id).error};start=&row.second;}if(!start||action.start_tick!=start->contact.tick||action.actor_id!=start->contact.actor_id||visit_appointment_meeting_finish(*meetings,start->invitation_fact_id))return {false,{},common_failure("VisitAppointmentActionSourceRequired",action.id).error};auto status=emit_visit_appointment_meeting_action_fields(w,*start);return {status.ok,status.ok,status.error};}
Status emit_visit_appointment_fact_payloads_fields(ProjectionWriter& w,const CommonStore& common,const VisitAppointmentState* state,const VisitAppointmentMeetingState* meetings){std::size_t n=0,m=0;for(const auto& row:common.state().facts.rows()){const auto& h=row.second;const bool a=invitation_kind(h.kind),b=meeting_kind(h.kind);if(!a&&!b&&h.domain!=visit_appointment_module&&h.domain!=visit_appointment_meeting_module)continue;if(h.id!=row.first||(!a&&!b)||(a&&(!state||h.domain!=visit_appointment_module))||(b&&(!meetings||h.domain!=visit_appointment_meeting_module)))return common_failure("VisitAppointmentFactMismatch",row.first);auto checked=w.object(row.first,h.field_order,[&](auto&out){return a?emit_visit_appointment_fact_fields(out,*state,row.first,&h):emit_visit_appointment_meeting_fact_fields(out,*meetings,row.first,&h);});if(!checked.ok)return checked;a?++n:++m;}if((state&&n!=state->offered.size()+state->collected.size()+state->accepted.size())||(meetings&&m!=meetings->started.size()+meetings->cancelled.size()+meetings->finished.size()))return common_failure("VisitAppointmentFactCoverageMismatch");return w.status();}
Outcome<BoundaryValue> visit_appointment_fact_payloads(const CommonStore& common,const VisitAppointmentState* state,const VisitAppointmentMeetingState* meetings){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto&out){return emit_visit_appointment_fact_payloads_fields(out,common,state,meetings);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
Status emit_visit_appointment_action_payloads_fields(ProjectionWriter& w,const CommonStore& common,const VisitAppointmentMeetingState* meetings){for(const auto& action:common.state().actions.rows())if(action.second.kind==visit_appointment_meeting_action_kind){const VisitAppointmentMeetingStarted* start=nullptr;if(meetings)for(const auto& row:meetings->started.rows())if(row.second.action_id==action.first){if(start)return common_failure("DuplicateVisitAppointmentAction",action.first);start=&row.second;}if(!start||action.second.id!=action.first||action.second.start_tick!=start->contact.tick||action.second.actor_id!=start->contact.actor_id||visit_appointment_meeting_finish(*meetings,start->invitation_fact_id))return common_failure("VisitAppointmentActionSourceRequired",action.first);auto emitted_action=w.object(action.first,[&](auto&out){return emit_visit_appointment_meeting_action_fields(out,*start);});if(!emitted_action.ok)return emitted_action;}return w.status();}
Outcome<BoundaryValue> visit_appointment_action_payloads(const CommonStore& common,const VisitAppointmentMeetingState* meetings){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto&out){return emit_visit_appointment_action_payloads_fields(out,common,meetings);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
Status validate_visit_appointment_json_payloads(const CommonStore& common,const VisitAppointmentState* state,const VisitAppointmentMeetingState* meetings,const BoundaryValue& value){try{using namespace boundary;auto expected=visit_appointment_fact_payloads(common,state,meetings);if(!expected.ok)return {false,{},expected.error};for(const auto& row:object(expected.value,"visit_appointments/facts")){const auto& actual=field(field(value,"facts","state"),row.first,"facts");if(!compare_boundary(actual,row.second).exact())return common_failure("VisitAppointmentFactPayloadMismatch",row.first);}auto actions=visit_appointment_action_payloads(common,meetings);if(!actions.ok)return {false,{},actions.error};for(const auto& row:object(actions.value,"visit_appointments/actions")){const auto& params=field(field(field(value,"actions","state"),row.first,"actions"),"params",row.first);if(!compare_boundary(params,row.second).exact())return common_failure("VisitAppointmentActionPayloadMismatch",row.first);}return common_success();}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
}
